// pages/usuarios/crear-usuario.component.ts
// Formulario para crear un nuevo usuario con cÃ³digo autoincremental.
// Validaciones: nombre/apellido solo letras y espacios, DNI 8 dÃ­gitos, telÃ©fono 9 dÃ­gitos.
import { Component, ChangeDetectorRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router } from '@angular/router';
import { HttpClient } from '@angular/common/http';
import { environment } from '../../../environments/environment';

interface FormUsuario {
  nombreCompleto:    string;
  apellidoCompleto:  string;
  dni:               string;
  telefono:          string;
  correo:            string;
  rol:               string;
  contrasena:        string;
  confirmarContrasena: string;
}

interface Errores {
  nombreCompleto:    string;
  apellidoCompleto:  string;
  dni:               string;
  telefono:          string;
  correo:            string;
  rol:               string;
  contrasena:        string;
  confirmarContrasena: string;
  general:           string;
}

@Component({
  selector: 'app-crear-usuario',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './crear-usuario.component.html',
  styleUrls: ['./crear-usuario.component.css']
})
export class CrearUsuarioComponent {

  private readonly URL_API = environment.apiUrl;

  cargando          = false;
  exitoso           = false;
  codigoGenerado    = '';
  contrasenaUsada   = '';
  mostrarContrasena = false;
  mostrarConfirmar  = false;

  // Autocompletado por DNI (RENIEC)
  buscandoDni           = false;
  private dniConsultado = '';

  form: FormUsuario = {
    nombreCompleto:     '',
    apellidoCompleto:   '',
    dni:                '',
    telefono:           '',
    correo:             '',
    rol:                '',
    contrasena:         '',
    confirmarContrasena: ''
  };

  errores: Errores = {
    nombreCompleto:     '',
    apellidoCompleto:   '',
    dni:                '',
    telefono:           '',
    correo:             '',
    rol:                '',
    contrasena:         '',
    confirmarContrasena: '',
    general:            ''
  };

  constructor(
    private http:   HttpClient,
    private router: Router,
    private cdr:    ChangeDetectorRef
  ) {}

  // Solo permite letras y espacios en campos de texto
  soloLetras(event: KeyboardEvent): void {
    const char = event.key;
    // Permite letras Unicode (incluye Ã±, Ã¡, Ã¼, etc.), espacios y teclas de control
    const teclasControl = ['Backspace', 'Delete', 'Tab', 'ArrowLeft', 'ArrowRight', 'Home', 'End'];
    if (teclasControl.includes(char)) return;
    if (!/^[\p{L} ]$/u.test(char)) {
      event.preventDefault();
    }
  }

  // Solo permite dÃ­gitos
  soloNumeros(event: KeyboardEvent): void {
    const char = event.key;
    if (!/^\d$/.test(char) && char !== 'Backspace' && char !== 'Delete' && char !== 'Tab' && char !== 'ArrowLeft' && char !== 'ArrowRight') {
      event.preventDefault();
    }
  }

  // Limitar longitud al pegar
  limitarPaste(event: ClipboardEvent, tipo: 'letras' | 'numeros', maxLen: number): void {
    event.preventDefault();
    const texto = event.clipboardData?.getData('text') ?? '';
    const filtrado = tipo === 'letras'
      ? texto.replace(/[^\p{L} ]/gu, '').slice(0, maxLen)
      : texto.replace(/\D/g, '').slice(0, maxLen);

    const input = event.target as HTMLInputElement;
    const inicio = input.selectionStart ?? 0;
    const fin    = input.selectionEnd ?? 0;
    const valor  = input.value;
    input.value  = valor.slice(0, inicio) + filtrado + valor.slice(fin);

    // Actualizar el ngModel manualmente
    input.dispatchEvent(new Event('input'));
  }

  // Se dispara al escribir el DNI; cuando llega a 8 digitos consulta RENIEC
  onDniChange(): void {
    const dni = (this.form.dni || '').trim();

    // Si borran el DNI se limpian los datos autocompletados
    if (dni.length < 8) {
      this.dniConsultado = '';
      return;
    }
    if (!/^\d{8}$/.test(dni)) return;
    if (dni === this.dniConsultado) return; // ya se consulto este DNI

    this.dniConsultado = dni;
    this.buscarDatosDni(dni);
  }

  // Llama al backend, que consulta RENIEC y devuelve nombres y apellidos
  private buscarDatosDni(dni: string): void {
    this.buscandoDni = true;
    this.errores.dni = '';

    this.http.get<any>(`${this.URL_API}/usuarios/dni/${dni}`).subscribe({
      next: (p) => {
        this.buscandoDni = false;
        this.form.nombreCompleto   = p.nombres   || '';
        this.form.apellidoCompleto = p.apellidos || '';
        this.errores.nombreCompleto   = '';
        this.errores.apellidoCompleto = '';
        this.cdr.detectChanges();
      },
      error: (err) => {
        this.buscandoDni  = false;
        this.dniConsultado = ''; // permite reintentar
        if (err.status === 404) {
          this.errores.dni = 'No se encontraron datos para ese DNI.';
        } else if (err.status === 400) {
          this.errores.dni = 'El DNI debe tener 8 dígitos.';
        } else {
          this.errores.dni = 'No se pudo consultar el DNI. Escribe los datos manualmente.';
        }
        this.cdr.detectChanges();
      }
    });
  }

  private validar(): boolean {
    let ok = true;
    this.errores = { nombreCompleto: '', apellidoCompleto: '', dni: '', telefono: '', correo: '', rol: '', contrasena: '', confirmarContrasena: '', general: '' };

    const soloLetrasRegex = /^[\p{L} ]+$/u;
    const emailRegex      = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

    if (!this.form.nombreCompleto.trim()) {
      this.errores.nombreCompleto = 'El nombre es obligatorio.'; ok = false;
    } else if (!soloLetrasRegex.test(this.form.nombreCompleto.trim())) {
      this.errores.nombreCompleto = 'Solo se permiten letras y espacios.'; ok = false;
    }

    if (!this.form.apellidoCompleto.trim()) {
      this.errores.apellidoCompleto = 'El apellido es obligatorio.'; ok = false;
    } else if (!soloLetrasRegex.test(this.form.apellidoCompleto.trim())) {
      this.errores.apellidoCompleto = 'Solo se permiten letras y espacios.'; ok = false;
    }

    if (!this.form.dni.trim()) {
      this.errores.dni = 'El DNI es obligatorio.'; ok = false;
    } else if (!/^\d{8}$/.test(this.form.dni.trim())) {
      this.errores.dni = 'El DNI debe tener exactamente 8 dÃ­gitos.'; ok = false;
    }

    if (!this.form.telefono.trim()) {
      this.errores.telefono = 'El telÃ©fono es obligatorio.'; ok = false;
    } else if (!/^\d{9}$/.test(this.form.telefono.trim())) {
      this.errores.telefono = 'El telÃ©fono debe tener exactamente 9 dÃ­gitos.'; ok = false;
    }

    if (!this.form.correo.trim()) {
      this.errores.correo = 'El correo es obligatorio.'; ok = false;
    } else if (!emailRegex.test(this.form.correo.trim())) {
      this.errores.correo = 'Ingresa un correo vÃ¡lido.'; ok = false;
    }

    if (!this.form.rol) {
      this.errores.rol = 'Selecciona un rol.'; ok = false;
    }

    if (!this.form.contrasena.trim()) {
      this.errores.contrasena = 'La contraseÃ±a es obligatoria.'; ok = false;
    } else if (this.form.contrasena.length < 8) {
      this.errores.contrasena = 'MÃ­nimo 8 caracteres.'; ok = false;
    } else if (!/[\p{Lu}]/u.test(this.form.contrasena)) {
      this.errores.contrasena = 'Debe incluir al menos 1 letra mayÃºscula.'; ok = false;
    } else if (!/[0-9]/.test(this.form.contrasena)) {
      this.errores.contrasena = 'Debe incluir al menos 1 nÃºmero.'; ok = false;
    } else if (!/[^a-zA-Z0-9]/.test(this.form.contrasena)) {
      this.errores.contrasena = 'Debe incluir al menos 1 carÃ¡cter especial (!@#$...).'; ok = false;
    }

    if (!this.form.confirmarContrasena.trim()) {
      this.errores.confirmarContrasena = 'Confirma la contraseÃ±a.'; ok = false;
    } else if (this.form.contrasena !== this.form.confirmarContrasena) {
      this.errores.confirmarContrasena = 'Las contraseÃ±as no coinciden.'; ok = false;
    }

    return ok;
  }

  onGuardar(): void {
    if (!this.validar()) return;

    this.cargando = true;
    this.contrasenaUsada = this.form.contrasena;

    this.http.post<any>(`${this.URL_API}/usuarios/crear`, {
      nombreCompleto:   this.form.nombreCompleto.trim(),
      apellidoCompleto: this.form.apellidoCompleto.trim(),
      dni:              this.form.dni.trim(),
      telefono:         this.form.telefono.trim(),
      correo:           this.form.correo.trim().toLowerCase(),
      rol:              this.form.rol,
      contrasena:       this.form.contrasena
    }).subscribe({
      next: (res) => {
        this.cargando       = false;
        this.exitoso        = true;
        this.codigoGenerado = res.codigo;
        this.cdr.detectChanges();
      },
      error: (err) => {
        this.cargando = false;
        if (err.status === 409) {
          this.errores.general = err.error?.message ?? 'El correo o DNI ya estÃ¡ registrado.';
        } else if (err.status === 400) {
          this.errores.general = 'Revisa los datos ingresados.';
        } else {
          this.errores.general = 'Error al crear el usuario. Intenta de nuevo.';
        }
        this.cdr.detectChanges();
      }
    });
  }

  onNuevoUsuario(): void {
    this.exitoso = false;
    this.codigoGenerado = '';
    this.form = { nombreCompleto: '', apellidoCompleto: '', dni: '', telefono: '', correo: '', rol: '', contrasena: '', confirmarContrasena: '' };
    this.mostrarContrasena = false;
    this.mostrarConfirmar  = false;
  }

  onVolver(): void {
    this.router.navigate(['/dashboard/admin']);
  }

  irAInicio(): void {
    this.router.navigate(['/dashboard/admin']);
  }

  irAGestionTickets(): void {
    this.router.navigate(['/dashboard/gestion-tickets']);
  }

  irAGestionIncidencias(): void {
    this.router.navigate(['/dashboard/gestion-incidencias']);
  }

  irAPanelUsuarios(): void {
    this.router.navigate(['/dashboard/panel-usuarios']);
  }

  irAAdministracion(): void {
    this.router.navigate(['/dashboard/administracion']);
  }
}